-- Run against the Unload Compare APPLICATION database.
GO
CREATE OR ALTER PROCEDURE dbo.usp_UC_SearchPO @Search nvarchar(100)=NULL AS BEGIN SET NOCOUNT ON; SELECT TOP(30) h.PONumber,h.VendorName,h.ContainerNumber,h.ReceivingDate,COUNT(i.POItemId) ItemCount FROM dbo.UC_POHeaderSource h LEFT JOIN dbo.UC_POItemSource i ON i.PONumber=h.PONumber WHERE h.IsActive=1 AND (NULLIF(LTRIM(RTRIM(@Search)),'') IS NULL OR h.PONumber LIKE '%'+@Search+'%' OR h.ContainerNumber LIKE '%'+@Search+'%') GROUP BY h.PONumber,h.VendorName,h.ContainerNumber,h.ReceivingDate ORDER BY h.PONumber DESC; END
GO
CREATE OR ALTER PROCEDURE dbo.usp_UC_GetPO @PONumber nvarchar(50) AS BEGIN SET NOCOUNT ON; SELECT h.PONumber,h.VendorName,h.ContainerNumber,h.ReceivingDate,(SELECT TOP 1 ReceivingId FROM dbo.UC_ReceivingHeader r WHERE r.PONumber=h.PONumber AND r.Status IN('Draft','In Progress','Ready for Verification') ORDER BY r.ModifiedDate DESC) ExistingReceivingId FROM dbo.UC_POHeaderSource h WHERE h.PONumber=@PONumber AND h.IsActive=1; SELECT SKU,ItemName,ExpectedQty,UOM,ExpectedPallets FROM dbo.UC_POItemSource WHERE PONumber=@PONumber ORDER BY POItemId; END
GO
CREATE OR ALTER PROCEDURE dbo.usp_UC_EnsureDraft @PONumber nvarchar(50),@UserName nvarchar(150) AS BEGIN SET NOCOUNT ON; SET XACT_ABORT ON; IF NOT EXISTS(SELECT 1 FROM dbo.UC_POHeaderSource WHERE PONumber=@PONumber AND IsActive=1) THROW 51000,'PO does not exist.',1; BEGIN TRAN; DECLARE @id int=(SELECT TOP 1 ReceivingId FROM dbo.UC_ReceivingHeader WITH(UPDLOCK,HOLDLOCK) WHERE PONumber=@PONumber AND Status IN('Draft','In Progress','Ready for Verification') ORDER BY ModifiedDate DESC); IF @id IS NULL BEGIN INSERT dbo.UC_ReceivingHeader(PONumber,VendorName,ContainerNumber,ReceivingDate,UnloadDate,Status,CreatedBy,ModifiedBy) SELECT PONumber,VendorName,ContainerNumber,COALESCE(ReceivingDate,CONVERT(date,GETDATE())),CONVERT(date,GETDATE()),'Draft',@UserName,@UserName FROM dbo.UC_POHeaderSource WHERE PONumber=@PONumber; SET @id=SCOPE_IDENTITY(); INSERT dbo.UC_AuditLog(ReceivingId,EntityType,EntityId,ActionType,FieldName,NewValue,ChangedBy) VALUES(@id,'ReceivingHeader',@id,'Create','Status','Draft',@UserName); END COMMIT; SELECT @id; END
GO
CREATE OR ALTER PROCEDURE dbo.usp_UC_SaveReceivingHeader @ReceivingId int=NULL,@PONumber nvarchar(50),@VendorName nvarchar(200)=NULL,@ContainerNumber nvarchar(100)=NULL,@ReceivingDate date,@UnloadDate date=NULL,@UnloadBy1 nvarchar(150)=NULL,@UnloadBy2 nvarchar(150)=NULL,@UnloadBy3 nvarchar(150)=NULL,@Status nvarchar(40),@Notes nvarchar(max)=NULL,@UserName nvarchar(150) AS BEGIN SET NOCOUNT ON; IF NOT EXISTS(SELECT 1 FROM dbo.UC_POHeaderSource WHERE PONumber=@PONumber) THROW 51000,'PO does not exist.',1; IF @Status NOT IN('Draft','In Progress','Ready for Verification','Verified','Completed') THROW 51000,'Invalid receiving status.',1; IF @Status='Ready for Verification' AND @UnloadDate IS NULL THROW 51000,'Unload Date is required before verification.',1; IF @Status='Ready for Verification' AND NULLIF(LTRIM(RTRIM(ISNULL(@UnloadBy1,''))),'') IS NULL THROW 51000,'Unload By 1 is required before verification.',1; IF @ReceivingId IS NULL OR NOT EXISTS(SELECT 1 FROM dbo.UC_ReceivingHeader WHERE ReceivingId=@ReceivingId) BEGIN IF EXISTS(SELECT 1 FROM dbo.UC_ReceivingHeader WITH(UPDLOCK,HOLDLOCK) WHERE PONumber=@PONumber AND Status IN('Draft','In Progress','Ready for Verification')) THROW 51000,'An active receiving record already exists for this PO.',1; INSERT dbo.UC_ReceivingHeader(PONumber,VendorName,ContainerNumber,ReceivingDate,UnloadDate,UnloadBy1,UnloadBy2,UnloadBy3,Status,Notes,CreatedBy,ModifiedBy) VALUES(@PONumber,@VendorName,@ContainerNumber,@ReceivingDate,@UnloadDate,@UnloadBy1,@UnloadBy2,@UnloadBy3,@Status,@Notes,@UserName,@UserName); SET @ReceivingId=SCOPE_IDENTITY(); INSERT dbo.UC_AuditLog(ReceivingId,EntityType,EntityId,ActionType,FieldName,NewValue,ChangedBy) VALUES(@ReceivingId,'ReceivingHeader',@ReceivingId,'Create','Status',@Status,@UserName); END ELSE BEGIN DECLARE @oldStatus nvarchar(40),@oldContainer nvarchar(100),@oldUnloadBy1 nvarchar(150),@oldUnloadBy2 nvarchar(150),@oldUnloadBy3 nvarchar(150),@oldUnloadDate date; SELECT @oldStatus=Status,@oldContainer=ContainerNumber,@oldUnloadDate=UnloadDate,@oldUnloadBy1=UnloadBy1,@oldUnloadBy2=UnloadBy2,@oldUnloadBy3=UnloadBy3 FROM dbo.UC_ReceivingHeader WHERE ReceivingId=@ReceivingId; UPDATE dbo.UC_ReceivingHeader SET VendorName=@VendorName,ContainerNumber=@ContainerNumber,ReceivingDate=@ReceivingDate,UnloadDate=@UnloadDate,UnloadBy1=@UnloadBy1,UnloadBy2=@UnloadBy2,UnloadBy3=@UnloadBy3,Status=@Status,Notes=@Notes,ModifiedBy=@UserName,ModifiedDate=SYSDATETIME() WHERE ReceivingId=@ReceivingId; IF ISNULL(@oldStatus,'')<>ISNULL(@Status,'') INSERT dbo.UC_AuditLog(ReceivingId,EntityType,EntityId,ActionType,FieldName,OldValue,NewValue,ChangedBy) VALUES(@ReceivingId,'ReceivingHeader',@ReceivingId,'Status Change','Status',@oldStatus,@Status,@UserName); IF ISNULL(@oldContainer,'')<>ISNULL(@ContainerNumber,'') INSERT dbo.UC_AuditLog(ReceivingId,EntityType,EntityId,ActionType,FieldName,OldValue,NewValue,ChangedBy) VALUES(@ReceivingId,'ReceivingHeader',@ReceivingId,'Header Change','ContainerNumber',@oldContainer,@ContainerNumber,@UserName); IF ISNULL(CONVERT(nvarchar(30),@oldUnloadDate,23),'')<>ISNULL(CONVERT(nvarchar(30),@UnloadDate,23),'') INSERT dbo.UC_AuditLog(ReceivingId,EntityType,EntityId,ActionType,FieldName,OldValue,NewValue,ChangedBy) VALUES(@ReceivingId,'ReceivingHeader',@ReceivingId,'Header Change','UnloadDate',CONVERT(nvarchar(30),@oldUnloadDate,23),CONVERT(nvarchar(30),@UnloadDate,23),@UserName); IF ISNULL(@oldUnloadBy1,'')<>ISNULL(@UnloadBy1,'') INSERT dbo.UC_AuditLog(ReceivingId,EntityType,EntityId,ActionType,FieldName,OldValue,NewValue,ChangedBy) VALUES(@ReceivingId,'ReceivingHeader',@ReceivingId,'Header Change','UnloadBy1',@oldUnloadBy1,@UnloadBy1,@UserName); IF ISNULL(@oldUnloadBy2,'')<>ISNULL(@UnloadBy2,'') INSERT dbo.UC_AuditLog(ReceivingId,EntityType,EntityId,ActionType,FieldName,OldValue,NewValue,ChangedBy) VALUES(@ReceivingId,'ReceivingHeader',@ReceivingId,'Header Change','UnloadBy2',@oldUnloadBy2,@UnloadBy2,@UserName); IF ISNULL(@oldUnloadBy3,'')<>ISNULL(@UnloadBy3,'') INSERT dbo.UC_AuditLog(ReceivingId,EntityType,EntityId,ActionType,FieldName,OldValue,NewValue,ChangedBy) VALUES(@ReceivingId,'ReceivingHeader',@ReceivingId,'Header Change','UnloadBy3',@oldUnloadBy3,@UnloadBy3,@UserName); END SELECT @ReceivingId; END
GO
CREATE OR ALTER PROCEDURE dbo.usp_UC_SaveReceivingItem @ReceivingId int,@ReceivingItemId int=NULL,@SKU nvarchar(80),@ItemName nvarchar(250),@ExpectedQty decimal(18,2),@UOM nvarchar(30)=NULL,@ExpectedPallets int=NULL,@EntryMode nvarchar(20),@ManualPhysicalQty decimal(18,2)=NULL,@ExpiryDate nvarchar(30)=NULL,@Nitrogen nvarchar(100)=NULL,@Notes nvarchar(max)=NULL,@UserName nvarchar(150) AS BEGIN SET NOCOUNT ON; DECLARE @po nvarchar(50)=(SELECT PONumber FROM dbo.UC_ReceivingHeader WHERE ReceivingId=@ReceivingId); IF NOT EXISTS(SELECT 1 FROM dbo.UC_POItemSource WHERE PONumber=@po AND SKU=@SKU) THROW 51000,'SKU does not belong to selected PO.',1; IF @ExpectedQty<0 OR ISNULL(@ManualPhysicalQty,0)<0 THROW 51000,'Quantity cannot be negative.',1; IF @EntryMode NOT IN('Pallet','Manual') THROW 51000,'Entry mode must be Pallet or Manual.',1; DECLARE @old nvarchar(60)=NULL; IF @ReceivingItemId IS NULL SELECT @ReceivingItemId=ReceivingItemId FROM dbo.UC_ReceivingItem WHERE ReceivingId=@ReceivingId AND SKU=@SKU; IF @ReceivingItemId IS NULL BEGIN INSERT dbo.UC_ReceivingItem(ReceivingId,SKU,ItemName,ExpectedQty,UOM,ExpectedPallets,EntryMode,ManualPhysicalQty,ExpiryDate,Nitrogen,TotalPhysicalQty,DifferenceQty,CompareStatus,Notes,ModifiedBy) VALUES(@ReceivingId,@SKU,@ItemName,@ExpectedQty,@UOM,@ExpectedPallets,@EntryMode,@ManualPhysicalQty,@ExpiryDate,@Nitrogen,CASE WHEN @EntryMode='Manual' AND @ManualPhysicalQty IS NOT NULL THEN @ManualPhysicalQty ELSE 0 END,CASE WHEN @EntryMode='Manual' AND @ManualPhysicalQty IS NOT NULL THEN @ManualPhysicalQty-@ExpectedQty ELSE 0 END,CASE WHEN @EntryMode='Manual' AND @ManualPhysicalQty IS NULL THEN 'Pending' WHEN @EntryMode='Pallet' THEN 'Pending' WHEN @ManualPhysicalQty=@ExpectedQty THEN 'Matched' WHEN @ManualPhysicalQty>@ExpectedQty THEN 'Over' ELSE 'Short' END,@Notes,@UserName); SET @ReceivingItemId=SCOPE_IDENTITY(); INSERT dbo.UC_AuditLog(ReceivingId,EntityType,EntityId,ActionType,FieldName,NewValue,ChangedBy) VALUES(@ReceivingId,'ReceivingItem',@ReceivingItemId,'Create','SKU',@SKU,@UserName); END ELSE BEGIN SELECT @old=CONVERT(nvarchar(60),TotalPhysicalQty) FROM dbo.UC_ReceivingItem WHERE ReceivingItemId=@ReceivingItemId; UPDATE dbo.UC_ReceivingItem SET ItemName=@ItemName,ExpectedQty=@ExpectedQty,UOM=@UOM,ExpectedPallets=@ExpectedPallets,EntryMode=@EntryMode,ManualPhysicalQty=@ManualPhysicalQty,ExpiryDate=@ExpiryDate,Nitrogen=@Nitrogen,Notes=@Notes,ModifiedBy=@UserName,ModifiedDate=SYSDATETIME() WHERE ReceivingItemId=@ReceivingItemId; END SELECT @ReceivingItemId; END
GO
CREATE OR ALTER PROCEDURE dbo.usp_UC_DeletePalletsForItem @ReceivingItemId int AS BEGIN SET NOCOUNT ON; DELETE dbo.UC_ReceivingPallet WHERE ReceivingItemId=@ReceivingItemId; END
GO
CREATE OR ALTER PROCEDURE dbo.usp_UC_InsertPallet @ReceivingItemId int,@PalletNo int,@Quantity decimal(18,2),@UserName nvarchar(150) AS BEGIN SET NOCOUNT ON; IF @PalletNo<1 OR @PalletNo>5 THROW 51000,'Only PAL-1 through PAL-5 are allowed.',1; IF @Quantity<0 THROW 51000,'Pallet quantity cannot be negative.',1; INSERT dbo.UC_ReceivingPallet(ReceivingItemId,PalletNo,Quantity,CreatedBy) VALUES(@ReceivingItemId,@PalletNo,@Quantity,@UserName); END
GO
CREATE OR ALTER PROCEDURE dbo.usp_UC_RecalculateReceiving @ReceivingId int,@UserName nvarchar(150) AS BEGIN SET NOCOUNT ON; DECLARE @Old TABLE(ReceivingItemId int PRIMARY KEY,OldPhysical decimal(18,2)); INSERT @Old SELECT ReceivingItemId,TotalPhysicalQty FROM dbo.UC_ReceivingItem WHERE ReceivingId=@ReceivingId; UPDATE i SET TotalPhysicalQty=CASE WHEN i.EntryMode='Manual' THEN ISNULL(i.ManualPhysicalQty,0) ELSE ISNULL(p.TotalQty,0) END,DifferenceQty=CASE WHEN (i.EntryMode='Manual' AND i.ManualPhysicalQty IS NULL) OR (i.EntryMode='Pallet' AND p.TotalQty IS NULL) THEN 0 ELSE (CASE WHEN i.EntryMode='Manual' THEN i.ManualPhysicalQty ELSE p.TotalQty END)-i.ExpectedQty END,CompareStatus=CASE WHEN i.EntryMode='Manual' AND i.ManualPhysicalQty IS NULL THEN 'Pending' WHEN i.EntryMode='Pallet' AND p.TotalQty IS NULL THEN 'Pending' WHEN (CASE WHEN i.EntryMode='Manual' THEN i.ManualPhysicalQty ELSE p.TotalQty END)=i.ExpectedQty THEN 'Matched' WHEN (CASE WHEN i.EntryMode='Manual' THEN i.ManualPhysicalQty ELSE p.TotalQty END)<i.ExpectedQty THEN 'Short' ELSE 'Over' END FROM dbo.UC_ReceivingItem i OUTER APPLY(SELECT SUM(Quantity) TotalQty FROM dbo.UC_ReceivingPallet p WHERE p.ReceivingItemId=i.ReceivingItemId)p WHERE i.ReceivingId=@ReceivingId; INSERT dbo.UC_AuditLog(ReceivingId,EntityType,EntityId,ActionType,FieldName,OldValue,NewValue,ChangedBy) SELECT @ReceivingId,'ReceivingItem',i.ReceivingItemId,'Quantity Change','TotalPhysicalQty',CONVERT(nvarchar(60),o.OldPhysical),CONVERT(nvarchar(60),i.TotalPhysicalQty),@UserName FROM dbo.UC_ReceivingItem i JOIN @Old o ON o.ReceivingItemId=i.ReceivingItemId WHERE i.ReceivingId=@ReceivingId AND o.OldPhysical<>i.TotalPhysicalQty; END
GO
CREATE OR ALTER PROCEDURE dbo.usp_UC_GetHistory @PONumber nvarchar(50)=NULL,@ContainerNumber nvarchar(100)=NULL,@Vendor nvarchar(200)=NULL,@Status nvarchar(40)=NULL,@User nvarchar(150)=NULL,@DateFrom date=NULL,@DateTo date=NULL AS BEGIN SET NOCOUNT ON; SELECT h.ReceivingId,h.PONumber,h.VendorName,h.ContainerNumber,h.ReceivingDate,h.UnloadDate,h.UnloadBy1,h.UnloadBy2,h.UnloadBy3,h.Status,COUNT(i.ReceivingItemId) ItemCount,COALESCE(SUM(CASE WHEN i.CompareStatus IN('Short','Over') THEN 1 ELSE 0 END),0) MismatchCount,h.ModifiedBy,h.ModifiedDate FROM dbo.UC_ReceivingHeader h LEFT JOIN dbo.UC_ReceivingItem i ON i.ReceivingId=h.ReceivingId WHERE (@PONumber IS NULL OR @PONumber='' OR h.PONumber LIKE '%'+@PONumber+'%') AND (@ContainerNumber IS NULL OR @ContainerNumber='' OR h.ContainerNumber LIKE '%'+@ContainerNumber+'%') AND (@Vendor IS NULL OR @Vendor='' OR h.VendorName LIKE '%'+@Vendor+'%') AND (@Status IS NULL OR @Status='' OR h.Status=@Status) AND (@User IS NULL OR @User='' OR h.ModifiedBy LIKE '%'+@User+'%') AND (@DateFrom IS NULL OR COALESCE(h.UnloadDate,h.ReceivingDate)>=@DateFrom) AND (@DateTo IS NULL OR COALESCE(h.UnloadDate,h.ReceivingDate)<=@DateTo) GROUP BY h.ReceivingId,h.PONumber,h.VendorName,h.ContainerNumber,h.ReceivingDate,h.UnloadDate,h.UnloadBy1,h.UnloadBy2,h.UnloadBy3,h.Status,h.ModifiedBy,h.ModifiedDate ORDER BY h.ModifiedDate DESC; END
GO
CREATE OR ALTER PROCEDURE dbo.usp_UC_GetReceivingDetails @ReceivingId int AS BEGIN SET NOCOUNT ON; SELECT * FROM dbo.UC_ReceivingHeader WHERE ReceivingId=@ReceivingId; SELECT * FROM dbo.UC_ReceivingItem WHERE ReceivingId=@ReceivingId ORDER BY ReceivingItemId; SELECT p.* FROM dbo.UC_ReceivingPallet p JOIN dbo.UC_ReceivingItem i ON i.ReceivingItemId=p.ReceivingItemId WHERE i.ReceivingId=@ReceivingId ORDER BY p.ReceivingItemId,p.PalletNo; SELECT DocumentId,OriginalFileName,ContentType,FileSizeBytes,ExtractionStatus,UploadedBy,UploadedDate FROM dbo.UC_UploadedDocument WHERE ReceivingId=@ReceivingId ORDER BY UploadedDate DESC; SELECT TOP(200) AuditId,ActionType,EntityType,FieldName,OldValue,NewValue,ChangedBy,ChangedDate FROM dbo.UC_AuditLog WHERE ReceivingId=@ReceivingId ORDER BY AuditId DESC; END
GO
CREATE OR ALTER PROCEDURE dbo.usp_UC_SetStatus @ReceivingId int,@Status nvarchar(40),@Notes nvarchar(max)=NULL,@UserName nvarchar(150) AS BEGIN SET NOCOUNT ON; DECLARE @old nvarchar(40)=(SELECT Status FROM dbo.UC_ReceivingHeader WHERE ReceivingId=@ReceivingId); IF @Status='Completed' AND @old<>'Verified' THROW 51000,'Only a verified record can be completed.',1; UPDATE dbo.UC_ReceivingHeader SET Status=@Status,Notes=COALESCE(NULLIF(@Notes,''),Notes),ModifiedBy=@UserName,ModifiedDate=SYSDATETIME() WHERE ReceivingId=@ReceivingId; INSERT dbo.UC_AuditLog(ReceivingId,EntityType,EntityId,ActionType,FieldName,OldValue,NewValue,ChangedBy) VALUES(@ReceivingId,'ReceivingHeader',@ReceivingId,'Status Change','Status',@old,@Status,@UserName); END
GO
CREATE OR ALTER PROCEDURE dbo.usp_UC_Verify @ReceivingId int,@Notes nvarchar(max)=NULL,@UserName nvarchar(150) AS BEGIN SET NOCOUNT ON; DECLARE @old nvarchar(40)=(SELECT Status FROM dbo.UC_ReceivingHeader WHERE ReceivingId=@ReceivingId); IF @old<>'Ready for Verification' THROW 51000,'Record must be Ready for Verification before it can be verified.',1; UPDATE dbo.UC_ReceivingHeader SET Status='Verified',VerifiedBy=@UserName,VerifiedDate=SYSDATETIME(),VerificationNotes=@Notes,ModifiedBy=@UserName,ModifiedDate=SYSDATETIME() WHERE ReceivingId=@ReceivingId; INSERT dbo.UC_Verification(ReceivingId,VerificationStatus,Comments,VerifiedBy) VALUES(@ReceivingId,'Verified',@Notes,@UserName); INSERT dbo.UC_AuditLog(ReceivingId,EntityType,EntityId,ActionType,FieldName,OldValue,NewValue,ChangedBy) VALUES(@ReceivingId,'ReceivingHeader',@ReceivingId,'Verify','Status',@old,'Verified',@UserName); END
GO
CREATE OR ALTER PROCEDURE dbo.usp_UC_LogImport @ReceivingId int,@FileName nvarchar(260),@TotalRows int,@MatchedRows int,@UnmatchedRows int,@ImportStatus nvarchar(40),@Details nvarchar(max)=NULL,@UserName nvarchar(150) AS BEGIN SET NOCOUNT ON; INSERT dbo.UC_ImportHistory(ReceivingId,FileName,TotalRows,MatchedRows,UnmatchedRows,ImportStatus,Details,ImportedBy) VALUES(@ReceivingId,@FileName,@TotalRows,@MatchedRows,@UnmatchedRows,@ImportStatus,@Details,@UserName); INSERT dbo.UC_AuditLog(ReceivingId,EntityType,ActionType,FieldName,NewValue,ChangedBy) VALUES(@ReceivingId,'Import','Excel Preview','FileName',@FileName,@UserName); END
GO
CREATE OR ALTER PROCEDURE dbo.usp_UC_SaveDocument @ReceivingId int,@OriginalFileName nvarchar(260),@StoredFileName nvarchar(260),@ContentType nvarchar(120),@FileSizeBytes bigint,@UserName nvarchar(150) AS BEGIN SET NOCOUNT ON; INSERT dbo.UC_UploadedDocument(ReceivingId,OriginalFileName,StoredFileName,ContentType,FileSizeBytes,UploadedBy) VALUES(@ReceivingId,@OriginalFileName,@StoredFileName,@ContentType,@FileSizeBytes,@UserName); DECLARE @id int=SCOPE_IDENTITY(); INSERT dbo.UC_AuditLog(ReceivingId,EntityType,EntityId,ActionType,FieldName,NewValue,ChangedBy) VALUES(@ReceivingId,'Document',@id,'Upload','FileName',@OriginalFileName,@UserName); SELECT @id; END
GO
CREATE OR ALTER PROCEDURE dbo.usp_UC_GetDocument @DocumentId int AS BEGIN SET NOCOUNT ON; SELECT StoredFileName,OriginalFileName,ContentType FROM dbo.UC_UploadedDocument WHERE DocumentId=@DocumentId; END
GO
